abstract class Vehicle{String name;boolean available=true;Vehicle(String n){name=n;}abstract double rate();double rent(int days){if(!available||days<1)throw new IllegalStateException("Unavailable");available=false;return rate()*days;}void giveBack(){available=true;}}class StandardCar extends Vehicle{StandardCar(String n){super(n);}double rate(){return 50;}}class LuxuryCar extends Vehicle{LuxuryCar(String n){super(n);}double rate(){return 100;}}class SUV extends Vehicle{SUV(String n){super(n);}double rate(){return 80;}}public class VehicleRentalDynamicPricing{public static void main(String[]x){Vehicle l=new LuxuryCar("Luxury Car A"),s=new StandardCar("Standard Car B");System.out.printf("%s rented for 3 days. Total charge: $%.2f%n",l.name,l.rent(3));System.out.printf("%s rented for 5 days. Total charge: $%.2f%n",s.name,s.rent(5));l.giveBack();System.out.println(l.name+" returned. Now available.");}}